        "zh": "在传统城市建设中，人们习惯用不透水的混凝土与沥青铺满地面，并依靠地下管网在暴雨后“快排”雨水。然而，随着极端强降雨事件频发，单纯依赖硬质排水管道往往不堪重负，导致城市内涝与干旱交替上演的矛盾局面。",
