        "py": "Jùtǐ éryán, hǎimián chéngshì bìngfēi tuīdǎo chónglái, ér shì tōngguò tòushuǐ pūzhuāng, xiàchénshì lǜdì, yǔshuǐ huāyuán yǔ shīdì gōngyuán děng shēngtài shèshī, shǐ yǔshuǐ shíxiàn zìrán jīcún yǔ shèntòu. Zhè bùjǐn dàfú jiǎnqīng le fánghóng páilào yālì, hái yǒuxiào bǔchōng le rìyì kuìfá de dìxiàshuǐ zīyuán, ràng chéngshì chóngguī rén yǔ zìrán héxié gòngshēng de liángxìng xúnhuán.",
