        "py": "Gǔrén céng yǐ pēngtiáo měiwèi tānggēng lái bǐyù 'hé' yǔ 'tóng' de qūbié: rúguǒ guō lǐ zhǐyǒu qīngyīsè de shuǐ, jíbiàn zài zěnme jiārè, hē qǐlái yě suǒrán wúwèi; wéiyǒu jiāng suān, tián, kǔ, là děng bùtóng wèidao de shícái àn bǐlì tiáohé, cái néng zhǔchū xiānměi fēngfù de jiāyáo. Yīnyuè yìrán, dāndiào chóngfù tóng yí ge yīnfú juéfēi yuèzhāng, duō zhǒng yuèqì gè sī qí zhí, bǐcǐ hūyìng, fāng néng zòuchū dòngrén jiāoxiǎng.",
        "vi": "Người xưa từng lấy việc nấu món canh ngon để ví von sự khác nhau giữa 'hòa' và 'đồng': nếu trong nồi chỉ có một màu nước trắng đơn thuần, dẫu đun nóng thế nào uống vào vẫn nhạt nhẽo vô vị; chỉ khi điều hòa các nguyên liệu mang vị chua, ngọt, đắng, cay khác nhau theo tỷ lệ mới nấu ra được mỹ vị đậm đà phong phú. Âm nhạc cũng vậy, lặp đi lặp lại đơn điệu một nốt nhạc tuyệt chẳng thành bản nhạc, nhiều nhạc cụ mỗi thứ đảm nhiệm phần việc riêng và hô ứng lẫn nhau mới tấu lên được bản giao hưởng lay động lòng người."
